// Typed access to the content migrated from the recovered site (src/content/*.json, generated by scripts/migrate.py).
// Server-side only: these modules are large and must not be imported from Client Components.
import siteJson from "@/content/site.json";
import homeJson from "@/content/home.json";
import pagesJson from "@/content/pages.json";
import postsJson from "@/content/posts.json";
import categoriesJson from "@/content/categories.json";
import coursesJson from "@/content/courses.json";
import courseCategoriesJson from "@/content/course-categories.json";
import shopJson from "@/content/shop.json";
import industriesJson from "@/content/industries.json";
import partnersJson from "@/content/partners.json";
import contactJson from "@/content/contact.json";

export type Img = { src: string; width: number | null; height: number | null; alt?: string; original?: string | null };
export type NavItem = { label: string; href: string; children?: NavItem[] };
export type Part =
  | { type: "html"; html: string }
  | { type: "posts"; paths: string[] }
  | { type: "form"; form: FormKind };
export type FormKind = "contact" | "quote" | "partner";
export type Page = {
  path: string;
  title: string;
  description: string;
  sections: Part[][];
  capture: string;
  archiveUrl: string;
};
export type Category = { slug: string; name: string; posts: string[] };
export type Post = {
  path: string;
  year: string;
  month: string;
  day: string;
  slug: string;
  title: string;
  date: string;
  urlDate: string;
  author: string | null;
  categories: { slug: string; name: string }[];
  tags: string[];
  featuredImage: Img | null;
  html: string;
  description: string;
  archiveUrl: string;
};
export type Course = {
  path: string;
  slug: string;
  title: string;
  price: string | null;
  shortDescription: string;
  html: string;
  packages: string[];
  image: Img | null;
  categories: { slug: string; name: string }[];
  description: string;
  archiveUrl: string;
};
export type CourseCategory = { slug: string; name: string; courses: string[] };
export type Industry = { name: string; headline: string; summary: string; features: string[]; image: Img | null; href: string };
export type Partner = { name: string; href: string; image: Img | null };

export const site = siteJson as {
  name: string;
  shortName: string;
  tagline: string;
  homeTitle: string;
  logo: Img;
  logoTransparent: Img;
  nav: NavItem[];
  ctaLabel: string;
  ctaHref: string;
  footerAbout: string;
  usefulLinks: NavItem[];
  contact: { address: string; phone: string; phoneHref: string; email: string };
  social: { network: string; href: string }[];
  copyright: string;
};
export const home = homeJson as {
  hero: { eyebrow: string; text: string };
  whyChoose: { heading: string; buttonLabel: string };
  servicesHeading: string;
  services: { title: string; href: string }[];
  labs: { heading: string; paragraphs: string[]; image: Img | null };
  certifications: { heading: string; image: Img | null };
  insightsHeading: string;
  insights: string[];
};
export const contact = contactJson as {
  offices: { name: string; address: string }[];
  phoneLines: string[];
  emails: string[];
  intro: string[];
};

const pages = pagesJson as unknown as Record<string, Page>;
export const shopPage = shopJson as unknown as Page;
export const posts = postsJson as Post[]; // newest first
export const categories = categoriesJson as Category[];
export const courses = coursesJson as Course[];
export const courseCategories = courseCategoriesJson as CourseCategory[];
export const industries = industriesJson as Industry[];
export const partners = partnersJson as Partner[];

export const POSTS_PER_PAGE = 10; // original /blog/page/N/ numbering (9 pages)
export const COURSES_PER_PAGE = 12; // original /shop/page/N/ numbering (11 pages)

export function getPage(path: string): Page | undefined {
  return pages[path];
}
export function allPagePaths(): string[] {
  return Object.keys(pages);
}

const postsByPath = new Map(posts.map((p) => [p.path, p]));
export function getPost(path: string): Post | undefined {
  return postsByPath.get(path);
}
export function postsByPaths(paths: string[]): Post[] {
  return paths.map((p) => postsByPath.get(p)).filter((p): p is Post => Boolean(p));
}
export function getCategory(slug: string): Category | undefined {
  return categories.find((c) => c.slug === slug);
}

const coursesByPath = new Map(courses.map((c) => [c.path, c]));
export function getCourse(slug: string): Course | undefined {
  return coursesByPath.get(`/product/${slug}/`);
}
/**
 * The original store contains a few duplicated courses (e.g. "-2" / "-copy" slugs) and some courses that reuse
 * another course's description. Both URLs are kept; metadata stays unique without inventing text.
 */
export function courseSeo(c: Course): { canonical: string; description: string } {
  const sameTitle = courses.find((x) => x.title === c.title);
  const sameDesc = courses.find((x) => x.description === c.description);
  return {
    canonical: sameTitle && sameTitle !== c ? sameTitle.path : c.path,
    description: sameDesc && sameDesc !== c && sameTitle === c ? `${c.title}: ${c.description}`.slice(0, 155).replace(/\s+\S*$/, "") + "…" : c.description,
  };
}

export function coursesByPaths(paths: string[]): Course[] {
  return paths.map((p) => coursesByPath.get(p)).filter((c): c is Course => Boolean(c));
}
export function getCourseCategory(slug: string): CourseCategory | undefined {
  return courseCategories.find((c) => c.slug === slug);
}

export function paginate<T>(items: T[], page: number, perPage: number) {
  const totalPages = Math.max(1, Math.ceil(items.length / perPage));
  return { items: items.slice((page - 1) * perPage, page * perPage), totalPages };
}
export function pageNumbers(count: number, perPage: number): string[] {
  const total = Math.ceil(count / perPage);
  return Array.from({ length: Math.max(0, total - 1) }, (_, i) => String(i + 2));
}

